// v23.xx (gfx15), HIS ORDER (2026-10-12) on the graphics program, item 3, the animation pass: HIT FLINCH. A hit used to show
// only as a red wash over the torso. Now the upper body (pack, torso, arms, gun and head) is knocked about 1.5 away from
// the shot and the head a little further, easing back as the hit fades. The direction is st.hitDir when a caller knows
// it, the push away from the player for a pillager (the same push as his hit jolt, animHitShift), and otherwise straight
// back from where the body faces. The legs stay planted, so it reads as a flinch and not a slide. CFG.gfxAnim 0 turns it
// off. Drawn only: no random numbers, nothing a fight reads.
var _fk=0, _fhx=0;
if(st.hurt>0&&!(CFG.gfxAnim===0)){
  var _fa=(typeof st.hitDir==='number'&&isFinite(st.hitDir))?st.hitDir:null, _hs=null;
  if(_fa===null&&st.own&&st.own.kind==='raider'&&typeof animHitShift==='function'){ try{ _hs=animHitShift(st.own); }catch(_ah){ _hs=null; } if(_hs&&(_hs.x||_hs.y)) _fa=Math.atan2(_hs.y,_hs.x); }
  if(_fa===null) _fa=face+Math.PI;
  _fk=Math.min(1,st.hurt/0.16); _fhx=Math.cos(_fa)*0.9*_fk;
  wc.save(); wc.translate(Math.cos(_fa)*1.5*_fk,Math.sin(_fa)*0.8*_fk);
}
var pw=6+pk*5;

