{v:'VER',what:'graphics program gfx15 (hit flinch): a body hit (hurt .16) is drawn with its head knocked at least 1 away from the shot, along st.hitDir when given and straight back from its facing when not, and back in place when the hit is over or the animation is off',
 run:function(){
   if(typeof drawOp!=='function') return 'SKIP: no painter here';
   var bad=[], w0=wc, a0=CFG.gfxAnim, cvs=document.createElement('canvas'), x2, heads=[], oRR;
   cvs.width=240; cvs.height=220; x2=cvs.getContext('2d'); if(!x2||!x2.roundRect) return 'SKIP: no canvas or no roundRect';
   function base(o){ var b={hero:0,moving:false,sprint:false,ads:false,hurt:0,rl:0,bulk:0,skin:'fair',own:{wep:null}}, k; for(k in o) b[k]=o[k]; return b; }
   function head(st,face){ heads.length=0; x2.setTransform(1,0,0,1,0,0); x2.clearRect(0,0,240,220); x2.setTransform(4,0,0,4,120,190); wc=x2;
     try{ drawOp(0,0,face||0,0,'#242832',0,0,'',0,st); } finally { wc=w0; x2.setTransform(1,0,0,1,0,0); }
     return heads.length?heads[0]:null; }
   try{
     oRR=x2.roundRect;
     x2.roundRect=function(x,y,w,h,r){ if(Math.abs(w-17)<1e-6&&Math.abs(h-15)<1e-6){ var m=x2.getTransform(); heads.push({x:(m.a*x+m.c*y+m.e)/4,y:(m.b*x+m.d*y+m.f)/4}); } return oRR.apply(this,arguments); };
     CFG.gfxAnim=undefined;
     var h0=head(base({hurt:0})), hE=head(base({hurt:0.16,hitDir:0})), hS=head(base({hurt:0.16,hitDir:Math.PI/2})), hB=head(base({hurt:0.16}),0);
     if(!h0||!hE||!hS||!hB) return 'SKIP: the head plate was not found';
     if(hE.x-h0.x<1) bad.push('a hit pushing east moves the head only '+(hE.x-h0.x).toFixed(2));
     if(hS.y-h0.y<0.5) bad.push('a hit pushing south does not move the head down ('+(hS.y-h0.y).toFixed(2)+')');
     if(h0.x-hB.x<1) bad.push('with no direction, a hit does not knock the head back from the facing ('+(h0.x-hB.x).toFixed(2)+')');
     CFG.gfxAnim=0; var hO=head(base({hurt:0.16,hitDir:0}));
     if(hO&&Math.abs(hO.x-h0.x)>1e-6) bad.push('with the animation off the head still flinches');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ wc=w0; CFG.gfxAnim=a0; delete x2.roundRect; }
   return bad.length?bad.join('; '):null; }},
